-- All records below are fictional placeholders for tender/demo review. Replace or delete before production launch.
-- Run only after applying supabase-schema.sql / content-type migration.

alter table public.site_content drop constraint if exists site_content_content_type_check;
alter table public.site_content add constraint site_content_content_type_check
  check (content_type in ('news','event','publication','chapter','executive','past_president','technical_division','document','project','committee','institutional_page'));

on conflict (content_type,slug) do update set
 title=excluded.title, summary=excluded.summary, body=excluded.body, metadata=excluded.metadata,
 published=excluded.published, event_start=excluded.event_start, event_end=excluded.event_end, updated_at=now();

